async function FINISH() {
  let wrd = 0;
  await V_SCORE();
  for (;;) {
    crlf();
    tell("Would you like to restart the game from the beginning, restore a saved game position, or end this session of the game?\n(Type RESTART, RESTORE, or QUIT):\n>");
    await read(g.P_INBUF, g.P_LEXV);
    wrd = get(g.P_LEXV, 1);
    if (wrd == W.RESTART) {
      await restart();
      tell("Failed.\n");
    } else if (wrd == W.RESTORE) {
      if (await restore()) {
        tell("Ok.\n");
      } else {
        tell("Failed.\n");
      }
    } else if (wrd == W.QUIT || wrd == W.Q) {
      await quit();
    }
  }
}

