async function DESCRIBE_ROOM(look$ = false) {
  let v$ = 0, str = 0, av = 0;
  v$ = look$ || g.VERBOSE;
  if (!g.LIT) {
    tell("It is pitch black.");
    if (!g.SPRAYED$) {
      tell(" You are likely to be eaten by a grue.");
    }
    crlf();
    if (g.HERE == DARK_2) {
      tell("The ground continues to slope upwards away from the lake. You can barely detect a dim light from the east.\n");
    }
    return false;
  }
  if (!(hasFlag(g.HERE, TOUCHBIT))) {
    setFlag(g.HERE, TOUCHBIT);
    v$ = true;
  }
  await NULL_F();
  if (loc(g.HERE) == ROOMS) {
    tell(D(g.HERE));
    if (hasFlag(av = loc(g.WINNER), VEHBIT)) {
      tell(", in the ", D(av));
    }
    crlf();
  }
  if (look$ || !g.SUPER_BRIEF) {
    av = loc(g.WINNER);
    if (v$ && (await apply(getProp(g.HERE, P.ACTION), M_LOOK))) {
      return true;
    } else if (v$ && (str = getProp(g.HERE, P.LDESC))) {
      tell(S(str), "\n");
    } else {
      await apply(getProp(g.HERE, P.ACTION), M_FLASH);
    }
    if (!(g.HERE == av) && hasFlag(av, VEHBIT)) {
      await apply(getProp(av, P.ACTION), M_LOOK);
    }
  }
  return true;
}

