async function CPEXIT() {
  let fx = 0, nfx = 0;
  g.CP_MOVED = false;
  if (g.PRSO == P.UP) {
    if (g.CPHERE == 1) {
      if (eq(get(g.CPTABLE, 2), -2)) {
        tell("With the help of the ladder, you exit the puzzle.\n");
        return CP_ANTE;
      } else {
        tell("The exit is too far above your head.\n");
        return false;
      }
    } else {
      tell("There is no way up.\n");
      return false;
    }
  } else if ((g.CPHERE == 33) && (g.PRSO == P.WEST) && g.CP_FLAG) {
    clearFlag(CP, TOUCHBIT);
    return CP_OUT;
  } else if (g.PRSO == P.DOWN) {
    tell("There's no way down here.\n");
    return false;
  } else if ((g.CPHERE == 33) && (g.PRSO == P.WEST)) {
    tell("The metal door bars the way.\n");
    return false;
  } else {
    fx = await LKP(g.PRSO, g.CPEXITS);
    if (((nfx = fx + g.CPHERE) > 36) || (nfx < 0) || (await ILLCP(g.CPHERE, fx))) {
      tell("There is a wall there.\n");
      return false;
    } else if (eq(Math.abs(fx), 1, 6)) {
      await CPMOVE(fx);
    } else if ((fx > 0) && (0 == get(g.CPTABLE, g.CPHERE + 6) || 0 == get(g.CPTABLE, g.CPHERE + (fx - 6)))) {
      await CPMOVE(fx);
    } else if ((fx < 0) && (0 == get(g.CPTABLE, g.CPHERE - 6) || 0 == get(g.CPTABLE, (g.CPHERE + 6) + fx))) {
      await CPMOVE(fx);
    } else {
      tell("There is a wall there.\n");
    }
    return false;
  }
}

async function ILLCP(one, two) {
  if (eq(mod(one, 6), 0) && (two == g.MINUS_FIVE || two == 1 || two == 7)) {
    return true;
  } else if (eq(mod(one, 6), 1) && (two == g.MINUS_SEVEN || two == g.MINUS_ONE || two == 5)) {
    return true;
  } else if ((one < 7) && (two < g.MINUS_FOUR)) {
    return true;
  } else if ((one > 30) && (two > 4)) {
    return true;
  } else {
    return false;
  }
}

