async function CPWALL_OBJECT() {
  let wl = 0, nwl = 0, nxt = 0, nnxt = 0, cnt = 0, top = 0, snap = false;
  if (isVerb(V.MOVE)) {
    tell("You can't grab the wall to pull it.\n");
    return true;
  } else if (isVerb(V.PUSH)) {
    nxt = await CPNEXT(g.CPHERE, g.PRSO);
    if (nxt == 0) {
      tell("The wall doesn't budge.\n");
      return true;
    }
    wl = get(g.CPTABLE, nxt);
    if (wl == 0) {
      tell("There is only a passage in that direction.\n");
      return true;
    } else if (wl == 1) {
      tell("The wall doesn't budge.\n");
      return true;
    } else if ((nnxt = await CPNEXT(nxt, g.PRSO)) == 0) {
      tell("The wall barely gives.\n");
      return true;
    } else if (!((nwl = get(g.CPTABLE, nnxt)) == 0)) {
      tell("The wall barely gives.\n");
      return true;
    } else {
      tell("The wall slides forward and you follow it");
      if (g.CPPUSH_FLAG) {
        tell(" to this position:\n");
      } else {
        g.SCORE = g.SCORE + 1;
        tell("....\nThe architecture of this region is getting complex, so that further descriptions will be diagrams of the immediate vicinity in a 3x3 grid. The walls here are rock, but of two different types - sandstone and marble. The following notations will be used:\n");
        await FIXED_FONT_ON();
        tell("\n  .. = your position (middle of grid)\n  MM = marble wall\n  SS = sandstone wall\n  ?? = unknown (blocked by walls)\n\n");
        await FIXED_FONT_OFF();
      }
      g.CPPUSH_FLAG = true;
      put(g.CPTABLE, nxt, 0);
      put(g.CPTABLE, nnxt, wl);
      if (!(nnxt == 0)) {
        top = 8 * (nnxt - 1);
        cnt = get(g.CPOBJS, top);
        loop1: for (;;) {
          if (cnt == 0) {
            break loop1;
          } else {
            top = top + 1;
            move(get(g.CPOBJS, top), CP_OUT);
            if (!snap) {
              snap = true;
              tell("You hear a soft \"snap\" from behind the wall you were pushing.\n");
            }
            cnt = cnt - 1;
          }
        }
      }
      if (nnxt == 1) {
        g.CPBLOCK_FLAG = true;
      }
      return await CPGOTO(nxt);
    }
  } else {
    return false;
  }
}

async function FIXED_FONT_ON() {
  return put(0, 8, get(0, 8) | 2);
}

async function FIXED_FONT_OFF() {
  return put(0, 8, get(0, 8) & (-3));
}

async function CPGOTO(fx) {
  let f = 0, x = 0, cnt = 0, top = 0;
  g.CP_MOVED = true;
  clearFlag(g.HERE, TOUCHBIT);
  top = 8 * (g.CPHERE - 1);
  cnt = top + 1;
  f = first(CP);
  loop1: for (;;) {
    x = next(f);
    if (!f) {
      break loop1;
    } else if (f == ADVENTURER) {
    } else {
      put(g.CPOBJS, cnt, f);
      remove(f);
      cnt = cnt + 1;
    }
    if (!x) {
      break loop1;
    } else {
      f = x;
    }
  }
  put(g.CPOBJS, top, (cnt - top) - 1);
  g.CPHERE = fx;
  top = 8 * (g.CPHERE - 1);
  cnt = get(g.CPOBJS, top);
  loop2: for (;;) {
    if (cnt == 0) {
      break loop2;
    } else {
      top = top + 1;
      move(get(g.CPOBJS, top), CP);
      cnt = cnt - 1;
    }
  }
  await PERFORM(V.LOOK);
  return true;
}

async function CPNEXT(rm, obj) {
  let fx = 0;
  fx = await LKP(obj, g.CPWALLS);
  if (await ILLCP(rm, fx)) {
    return 0;
  } else {
    return rm + fx;
  }
}

async function CPDOOR_F() {
  if ((g.HERE == CP) && !(g.CPHERE == 33)) {
    tell("You can't see any steel door here.\n");
    return true;
  } else if (isVerb(V.OPEN)) {
    if (g.CP_FLAG) {
      tell("The steel door has already opened.\n");
      return true;
    } else {
      tell("You can't force it open.\n");
      return true;
    }
  } else if (isVerb(V.CLOSE)) {
    if (g.CP_FLAG) {
      tell("There doesn't seem to be any way to close it.\n");
      return true;
    } else {
      tell("Do you think it isn't already?\n");
      return true;
    }
  } else if (isVerb(V.MUNG)) {
    tell("The door is, to a first approximation, indestructible.\n");
    return true;
  } else if (isVerb(V.KNOCK)) {
    tell("Besides a great amount of reverberation, nothing happens.\n");
    return true;
  } else {
    return false;
  }
}

async function CP_ROOM(rarg) {
  if (rarg == M_ENTER) {
    return g.CPHERE = g.PRSO == P.DOWN ? 1 : 33;
  } else if (rarg == M_LOOK) {
    if (g.CPPUSH_FLAG) {
      return await CPWHERE();
    } else {
      tell("You are in a small square room bounded to the north and west with marble walls and to the east and south with sandstone walls.\n");
      return true;
    }
  } else {
    return false;
  }
}

async function CPNS(num) {
  if ((num > 36) || (num < 1)) {
    return 1;
  } else {
    return get(g.CPTABLE, num);
  }
}

async function CPEW(num, foo) {
  if (eq(mod(num, 6), foo)) {
    return 1;
  } else {
    return get(g.CPTABLE, num);
  }
}

async function CPWHERE() {
  let n_ = (await CPNS(g.CPHERE + (-6))), s_ = (await CPNS(g.CPHERE + 6)), e = (await CPEW(g.CPHERE + 1, 1)), w_ = (await CPEW(g.CPHERE + (-1), 0));
  await FIXED_FONT_ON();
  tell("      +");
  await CP_CORNER(g.MINUS_SEVEN, n_, w_);
  tell(" ");
  await CP_ORTHO(n_);
  tell(" ");
  await CP_CORNER(g.MINUS_FIVE, n_, e);
  tell("+\n");
  tell("West  +");
  await CP_ORTHO(w_);
  tell(" .. ");
  await CP_ORTHO(e);
  tell("+  East\n");
  tell("      +");
  await CP_CORNER(5, s_, w_);
  tell(" ");
  await CP_ORTHO(s_);
  tell(" ");
  await CP_CORNER(7, s_, e);
  tell("+\n");
  await FIXED_FONT_OFF();
  if (g.CPHERE == 1) {
    tell("In the ceiling above you is a large circular opening.\n");
  } else if (g.CPHERE == 22) {
    tell("The center of the floor here is noticeably depressed.\n");
  } else if (g.CPHERE == 33) {
    tell("In the center of the west wall is a steel door which is ");
    if (g.CP_FLAG) {
      tell("open");
    } else {
      tell("closed");
    }
    tell(". On one side of the door is a narrow slot.\n");
  }
  if (e == (-2)) {
    tell("There is a ladder here, firmly attached to the east wall.\n");
  }
  if (w_ == (-3)) {
    tell("There is a ladder here, firmly attached to the west wall.\n");
    return true;
  } else {
    return false;
  }
}

async function CP_ORTHO(contents) {
  if (contents == 0) {
    tell("  ");
    return true;
  } else if (contents == 1) {
    tell("MM");
    return true;
  } else {
    tell("SS");
    return true;
  }
}

async function CP_CORNER(dir, col, row) {
  let locn = 0;
  locn = g.CPHERE + dir;
  if (!(col == 0) && !(row == 0)) {
    tell("??");
    return true;
  } else if (await ILLCP(g.CPHERE, dir)) {
    tell("MM");
    return true;
  } else if ((col = (locn < 1) || (locn > 36) ? 1 : get(g.CPTABLE, locn)) == 0) {
    tell("  ");
    return true;
  } else if (col == 1) {
    tell("MM");
    return true;
  } else {
    tell("SS");
    return true;
  }
}

