async function EWTELL(rm) {
  let east$ = false, m1$ = false, mwin = 0;
  if ((rm == MRAE || rm == MRBE || rm == MRCE) || (rm == MRGE || rm == MRCE)) {
    east$ = true;
  }
  if (eq(g.MDIR + (east$ ? 0 : 180), 180)) {
    m1$ = true;
  }
  if (m1$) {
    mwin = g.MR1_FLAG;
  } else {
    mwin = g.MR2_FLAG;
  }
  tell("You are in a narrow room, whose ", S((east$ ? "west" : "east")), " wall is a large ", S((mwin ? "mirror." : "wooden panel which once contained a mirror.")), "\n");
  if (m1$ && g.MIRROR_OPEN_FLAG) {
    tell(S((mwin ? "The mirror is mounted on a panel which has been opened outward." : "The panel has been opened outward.")), "\n");
  }
  tell("The opposite wall is solid rock.\n");
  return true;
}

