async function LOOK_TO(rmn, rms) {
  let north$ = false, ntell = false, stell = false, mir$ = 0, m1$ = false, dir = 0;
  if (!(g.HERE == MREYE || g.HERE == FRONT_DOOR)) {
    tell("This is a part of the long hallway. The east and west walls are dressed stone. In the center of the hall is a shallow stone channel. In the center of the room the channel widens into a large hole around which is engraved a compass rose.\n");
  }
  if (g.HERE == MRG) {
    g.GUARDIANS_SEEN = true;
    tell("On either side of you are identical stone statues holding bludgeons. They appear ready to strike, though, for the moment, they remain impassive.\n");
  } else if (g.HERE == MRC) {
    g.GUARDIANS_SEEN = true;
    tell("Somewhat to the north", S(g.GUARDSTR), "\n");
    ntell = true;
  } else if (g.HERE == FRONT_DOOR) {
    tell("You are in a north-south hallway which ends, to the north, at a large wooden door.\n");
    ntell = true;
  } else if (g.HERE == MRD) {
    g.GUARDIANS_SEEN = true;
    tell("Somewhat to the south", S(g.GUARDSTR), "\n");
    stell = true;
  } else if (g.HERE == MRA) {
    tell("The hallway continues to the south.\n");
    stell = true;
  }
  if (g.MLOC == rmn || g.MLOC == rms) {
    if (g.MLOC == rmn) {
      north$ = true;
      ntell = true;
      (dir = "nor");
    } else {
      stell = true;
      (dir = "sou");
    }
    mir$ = north$ && (g.MDIR > 180) && (g.MDIR < 359) ? (m1$ = true, g.MR1_FLAG) : (!north$ && (g.MDIR > 0) && (g.MDIR < 179) ? (m1$ = true, g.MR1_FLAG) : g.MR2_FLAG);
    if (mod(g.MDIR, 180) == 0) {
      tell("The ", S(dir), "th side of the room is divided by a wooden wall into small hallways to the ");
      tell(S(dir), "theast and ");
      tell(S(dir), "thwest.\n");
    } else {
      tell(S((mir$ ? "A large mirror fills the " : "A large panel fills the ")), S(dir), "th side of the hallway.\n");
      if (m1$ && g.MIRROR_OPEN_FLAG) {
        tell(S((mir$ ? "The mirror is mounted on a panel which has been opened outward." : "The panel has been opened outward.")), "\n");
      }
    }
  }
  if (!ntell && !stell) {
    tell("The corridor continues north and south.\n");
  } else if (!ntell) {
    tell("The corridor continues north.\n");
  } else if (!stell) {
    tell("The corridor continues south.\n");
  }
  return true;
}

