async function MIRROR_HERE$(rm) {
  let tmp = 0;
  if ((g.HERE == MRAE || g.HERE == MRAW || g.HERE == MRBE) || (g.HERE == MRBW || g.HERE == MRCE || g.HERE == MRCW) || (g.HERE == MRGE || g.HERE == MRGW || g.HERE == MRDE) || (g.HERE == MRDW)) {
    if (180 == (g.MDIR + ((rm == MRAE || rm == MRBE || rm == MRCE) || (rm == MRGE || rm == MRDE) ? 0 : 180))) {
      return 1;
    } else {
      return 2;
    }
  } else if (mod(g.MDIR, 180) == 0) {
    return false;
  } else if (tmp = await MIRROR_DIR$(P.NORTH, rm)) {
    return tmp;
  } else if (tmp = await MIRROR_DIR$(P.SOUTH, rm)) {
    return tmp;
  } else {
    return false;
  }
}

async function MIRROR_FUNCTION() {
  let mirror = 0;
  if (!(mirror = await MIRROR_HERE$(g.HERE))) {
    tell("You can't see any mirror here.\n");
    return true;
  } else if (isVerb(V.OPEN, V.MOVE)) {
    tell("You don't see a way to open the mirror here.\n");
    return true;
  } else if (isVerb(V.LOOK_INSIDE)) {
    if (((mirror == 1) && g.MR1_FLAG) || g.MR2_FLAG) {
      if (g.INVIS) {
        tell("Amazingly, you have no reflection!\n");
        return true;
      } else {
        tell("A disheveled adventurer stares back at you.\n");
        return true;
      }
    } else {
      tell("You have destroyed the mirror, or have you forgotten?\n");
      return true;
    }
  } else if (isVerb(V.MUNG)) {
    if (mirror == 1) {
      if (g.MR1_FLAG) {
        g.MR1_FLAG = false;
        tell("The mirror breaks, revealing a wooden panel behind it. The glistening fragments of mirror quietly sparkle into nonexistance.\n");
        return true;
      } else {
        tell("The mirror has already been broken.\n");
        return true;
      }
    } else if (g.MR2_FLAG) {
      g.MR2_FLAG = false;
      tell("The mirror breaks, revealing a wooden panel behind it. The glistening fragments of mirror quietly sparkle into nonexistance.\n");
      return true;
    } else {
      tell("The mirror has already been broken.\n");
      return true;
    }
  } else if (((mirror == 1) && !g.MR1_FLAG) || !g.MR2_FLAG) {
    tell("There's no mirror left.\n");
    return true;
  } else if (isVerb(V.PUSH)) {
    tell(S((mirror == 1 ? "The mirror is mounted on a wooden panel which moves slightly inward as you push, and back out when you let go. It feels fragile." : "The mirror is unyielding, but seems fragile.")), "\n");
    return true;
  } else {
    return false;
  }
}

