async function BEAM_FUNCTION() {
  let pro = 0, pri = 0;
  if (isVerb(V.LEAP)) {
    tell("You jump over the beam and into the hallway.\n");
    await GOTO(MRA);
    return true;
  } else if (isVerb(V.FOLLOW)) {
    tell("It simply crosses the northern end of the room, so there's nowhere to follow it.\n");
    return true;
  } else if (isVerb(V.EXAMINE)) {
    tell("The red beam of light crosses the north end of the room only an inch or so above the floor.");
    if (await BEAM_STOPPED$()) {
      tell(" The beam is broken by a ", D(g.BEAM_BREAKER), " lying on the ground.");
    }
    return crlf();
  } else if (isVerb(V.PUT, V.MUNG)) {
    if (isVerb(V.PUT)) {
      pri = g.PRSO;
      pro = g.PRSI;
    } else {
      pri = g.PRSI;
      pro = g.PRSO;
    }
    if (!pri || !(pro == BEAM)) {
      return false;
    } else if (loc(pri) == g.WINNER) {
      move(pri, g.HERE);
      g.BEAM_BREAKER = pri;
      tell("The beam is now interrupted by a ", D(pri), " lying on the floor.\n");
      return true;
    } else if (loc(pri) == g.HERE) {
      tell("The ", D(pri), " already breaks the beam.\n");
      return true;
    } else if (pri == HANDS) {
      tell("The beam is broken briefly as it passes through.\n");
      return true;
    } else {
      tell("You're not holding the ", D(pri), ".\n");
      return true;
    }
  } else if (isVerb(V.TAKE) && (g.PRSO == BEAM)) {
    tell("No doubt you have a bottle of moonbeams as well.\n");
    return true;
  } else {
    return false;
  }
}

