async function MOVE_CELL_OBJECTS() {
  let top = 0, cnt = 0, f = 0, x = 0;
  top = 8 * (g.LCELL - 1);
  cnt = top + 1;
  f = first(CELL);
  if (f) {
    loop1: for (;;) {
      x = next(f);
      if (!f) {
        break loop1;
      } else {
        put(g.CELLOBJS, cnt, f);
        remove(f);
        cnt = cnt + 1;
      }
      if (!x) {
        break loop1;
      } else {
        f = x;
      }
    }
  }
  put(g.CELLOBJS, top, (cnt - top) - 1);
  top = 8 * (g.PNUMB - 1);
  cnt = get(g.CELLOBJS, top);
  for (;;) {
    if (cnt == 0) {
      return true;
    } else {
      top = top + 1;
      move(get(g.CELLOBJS, top), CELL);
      cnt = cnt - 1;
    }
  }
}

