async function OLD_MAN_F(rarg = false) {
  if (rarg == M_OBJDESC) {
    if (g.OLD_MAN_AWAKE) {
      tell("There is an old man huddled in the corner, eyeing you cautiously. He looks weak and tired.\n");
      return true;
    } else {
      tell("An old and wizened man is huddled, asleep, in the corner. He is snoring loudly, and looks quite weak and frail.\n");
      return true;
    }
  } else if (isVerb(V.GIVE) && (g.PRSI == OLD_MAN)) {
    if (g.OLD_MAN_AWAKE) {
      if (g.PRSO == WAYBREAD) {
        remove(WAYBREAD);
        tell("He looks up at you and takes the waybread. Slowly, he eats the bread and pauses when he is finished. He starts to speak: \"Perhaps what you seek is through there!\" He points at the carved wall to the north, where you now notice the bare outline of a secret door. When you turn back, the old man is gone!\n");
        clearFlag(SECRET_DOOR, INVISIBLE);
        g.OLD_MAN_GONE = true;
        return remove(OLD_MAN);
      } else if (loc(WAYBREAD) == g.WINNER) {
        tell("He refuses your offer but motions with his arm to the waybread in your hand.\n");
        return true;
      } else {
        tell("The old man refuses the ", D(g.PRSO), " with a wave of his hand.\n");
        return true;
      }
    } else {
      tell("He is asleep!\n");
      return true;
    }
  } else if (isVerb(V.EXAMINE)) {
    if (g.OLD_MAN_AWAKE) {
      tell("The old man is barely awake and appears to nod off every few moments. He has bright eyes, which appear to see right through your body.\n");
      return true;
    } else {
      tell("The man is very, very old and wizened. He has a long, stringy beard and is snoring quite loudly.\n");
      return true;
    }
  } else if (isVerb(V.LISTEN)) {
    if (g.OLD_MAN_AWAKE) {
      tell("He isn't talking.\n");
      return true;
    } else {
      tell("He is snoring like a buzz saw.\n");
      return true;
    }
  } else if (await HELLO$(OLD_MAN)) {
    if (g.OLD_MAN_AWAKE) {
      tell("He nods at you without seeming to have understood.\n");
      return true;
    } else {
      tell("He is sleeping soundly and does not respond.\n");
      return true;
    }
  } else if (isVerb(V.SHAKE, V.ALARM)) {
    tell("The old man is roused to consciousness. He peers at you through eyes which appear much younger and stronger than his frail body and waits, as if expecting something to happen.\n");
    g.OLD_MAN_AWAKE = true;
    return enable(await QUEUE(I_OLD_MAN_SLEEPS.id, 3));
  } else if (isVerb(V.ATTACK, V.MUNG)) {
    tell("The attack seems to have left the old man unharmed! You watch in awe as he rises to his feet and seems to tower above you. He peers down menacingly, then sadly and wearily. \"Not yet,\" he mourns, and vanishes in a puff of smoke.\n");
    g.OLD_MAN_GONE = true;
    return remove(OLD_MAN);
  } else {
    return false;
  }
}

