async function JIGS_UP(desc, player$ = false) {
  g.SWORD_STATE = 0;
  g.P_STRENGTH = 5;
  g.S_STRENGTH = 5;
  tell(S(desc), "\n");
  if (!(g.YEAR == YEAR_PRESENT)) {
    await quit();
  }
  if (!(ADVENTURER == g.WINNER)) {
    tell(" \n    ****  The ", D(g.WINNER), " has died  **** \n\n");
    remove(g.WINNER);
    g.WINNER = ADVENTURER;
    g.HERE = loc(g.WINNER);
    return M_FATAL;
  }
  tell("\n    ****  You have died  ****\n\n");
  if ((g.DEATHS = g.DEATHS + 1) > 3) {
    tell("You feel yourself disembodied in a deep blackness. A voice from the void speaks:  \"I have waited a long age for you, my friend, but perhaps it has been another that I have been seeking. Good night, oh worthy adventurer!\" It is the last you hear.\n");
    await quit();
  } else {
    tell("You find yourself deep within the earth in a barren prison cell. Outside the iron-barred window, you can see a great, fiery pit. Flames leap up and very nearly sear your flesh. After a while, footfalls can be heard in the distance, then closer and closer.... The door swings open, and in walks an old man.\n\nHe is dressed simply in a hood and cloak, wearing an amulet and ring, carrying an old book under one arm, and leaning on a wooden staff. A single key, as if to a massive prison cell, hangs from his belt.\n\nHe raises the staff toward you and you hear him speak, as if in a dream: \"I await you, though your journey be long and full of peril. Go then, and let me not wait long!\" You feel some great power well up inside you and you fall to the floor. The next moment, you are awakening, as if from a deep slumber.\n");
  }
  move(g.CURRENT_LAMP, ZORK2_STAIR);
  if ((loc(KEY) == g.WINNER) && ((g.HERE == DARK_1 || g.HERE == DARK_2 || g.HERE == KEY_ROOM) || (g.HERE == AQ_1 || g.HERE == AQ_2))) {
    move(KEY, KEY_ROOM);
  }
  crlf();
  await GOTO(ZORK2_STAIR);
  g.P_CONT = false;
  await RANDOMIZE_OBJECTS();
  await KILL_INTERRUPTS();
  return M_FATAL;
}

async function RANDOMIZE_OBJECTS() {
  let r = false, f = 0, n_ = 0, l = 0;
  n_ = first(g.WINNER);
  for (;;) {
    f = n_;
    if (!f) {
      return true;
    }
    n_ = next(f);
    move(f, await RANDOM_ELEMENT(g.DEAD_OBJ_LOCS));
  }
}

