async function GO_ON_LAKE() {
  let f = 0, n_ = 0, told = false;
  if (f = first(g.WINNER)) {
    loop1: for (;;) {
      n_ = next(f);
      if (!(hasFlag(f, WEARBIT))) {
        move(f, IN_LAKE);
        if (f == TORCH) {
          remove(TORCH);
          move(FRIED_TORCH, IN_LAKE);
        } else if (f == LAMP) {
          move(LAMP, LOCAL_GLOBALS);
          move(FRIED_LAMP, IN_LAKE);
          g.CURRENT_LAMP = FRIED_LAMP;
        } else if (f == WAYBREAD) {
          remove(WAYBREAD);
        }
        if (!told) {
          told = true;
          tell("The shock of entering the frigid water has made you drop all your possessions into the lake!\n");
        }
      }
      if (!n_) {
        break loop1;
      } else {
        f = n_;
      }
    }
  }
  if (!told) {
    tell("You are nearly paralyzed by the icy waters as you swim into the center of the lake.\n");
  }
  crlf();
  await GOTO(ON_LAKE);
  g.LAKE_TIME = 0;
  return enable(await QUEUE(I_ON_LAKE.id, -1));
}

async function I_ON_LAKE() {
  g.LAKE_TIME = g.LAKE_TIME + 1;
  if ((10 > random(100)) && (g.HERE == ON_LAKE) && !g.INVIS) {
    tell("A giant roc, previously hidden among the rocks, is heading right toward you, its mouth gaping wide!\n");
    return enable(await QUEUE(I_ROC.id, 2));
  } else if (!(g.HERE == ON_LAKE || g.HERE == IN_LAKE)) {
    await QUEUE(I_ON_LAKE.id, 0);
    await QUEUE(I_IN_LAKE.id, 0);
    await QUEUE(I_ROC.id, 0);
    return false;
  } else if (g.LAKE_TIME == 4) {
    tell("The icy waters are taking their toll. You will not be able to hold out much longer.\n");
    return true;
  } else if (g.LAKE_TIME == 6) {
    tell("You are becoming very weak. You had better leave the water before you drown!\n");
    return true;
  } else if (g.LAKE_TIME == 8) {
    await QUEUE(I_ON_LAKE.id, 0);
    await QUEUE(I_IN_LAKE.id, 0);
    await QUEUE(I_ROC.id, 0);
    return (await JIGS_UP("Your strength gives out, and you drown in the frigid waters."));
  } else {
    return false;
  }
}

